import{_ as o,l as r,o as e,c as s,v as t,p as l,x as i,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"AWQ 原文","description":"","frontmatter":{"title":"AWQ 原文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lin-awq.md","filePath":"llm/lin-awq.md","lastUpdated":1789023840000}'),A={name:"llm/lin-awq.md"};function c(m,a,T,u,E,P){const n=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="awq-原文" tabindex="-1">AWQ 原文 <a class="header-anchor" href="#awq-原文" aria-label="Permalink to &quot;AWQ 原文&quot;">​</a></h1><div class="epigraph"><p>我们并不去保护「权重大」的通道，而是保护那些乘上长期巨大激活之后会主导输出的通道；把它们先放大再取整，舍入相对变小，不必用 Hessian 去拟合校准句。</p><footer>—— Lin、Tang、Han 等，AWQ: Activation-aware Weight Quantization，MLSys 2024</footer></div><p>Ji Lin、Jiaming Tang、Haotian Tang、Shang Yang、Wei-Ming Chen、Wei-Chen Wang、Guangxuan Xiao、Xingyu Dang、Chuang Gan 与 Song Han 的 MLSys 2024 论文（arXiv:2306.00978）把 4-bit 权重量化从「校准集上的层输出最小二乘」换成 <strong>激活感知的通道保护</strong>。算法落地见 <a href="/llm/awq">AWQ</a>。本篇按原文写：他们测了什么模型、为何把「不重构」写成贡献、TinyChat 的加速合同绑在哪类硬件上，以及指令微调与视觉–语言投影为什么被放进主表而不是附录。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Round-to-nearest 把同一组里的大小权重塞进同一尺度。大权重相对误差小，但输出误差是 \\((w-\\hat{w})x\\)：小权重若乘的是巨大激活，照样能主导。当时 GPTQ 已经能在 OPT-175B 上把权重量到 3–4 bit，层输出 MSE 在校准句上很好。原文提出的裂缝是另一条：补偿可能把权重改到对校准语料最优、对指令分布或视觉 token 不优；端侧还希望量化快、不必对每个下游任务重跑二阶过程。</p><p>作者同时面对部署约束。目标位宽是 <strong>W4A16</strong>，不是 W8A8：decode 与端侧小 batch 的墙在权重加载，激活保持半精度仍然划算。混合精度把显著通道留在 FP16，精度好，但稀疏通道布局让 GPU 核变慢，端侧更难写。需要的是：仍走稠密 4-bit 网格，却把误差预算偏向显著列。</p><h3 id="显著通道来自激活-不是来自" tabindex="-1">显著通道来自激活，不是来自 \\(|W|\\) <a class="header-anchor" href="#显著通道来自激活-不是来自" aria-label="Permalink to &quot;显著通道来自激活，不是来自 $|W|$&quot;">​</a></h3><p>权重大小是静态的；显著是 \\(w\\) 与 \\(x\\) 的搭配。只看 \\(|W|\\) 的 RTN 或只看权重量级的稀疏，会漏掉「权重普通、激活极大」的列，也会过度保护「权重大、激活长期接近零」的死通道。原文用校准激活的通道幅度定义显著子集，默认约 <strong>1%</strong>。校准仍然需要，但用途是统计，不是逐列拟合。这是标题里 activation-aware 的本意，也是和 GPTQ 的评测合同分叉处。</p><p><span class="marginnote">不要把 AWQ 的通道缩放写成 <a href="/llm/smoothquant">SmoothQuant</a>。SmoothQuant 把激活异常值的难度迁到权重上，为的是两边都能 INT8；AWQ 把显著权重抬高，为的是权重量化误差更小，激活在推理时仍是高精度，只是先除 \\(s\\)。公式都是对角缩放，目的相反。原文对照见 <a href="/llm/xiao-smoothquant">SmoothQuant 原文</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对一层 \\(Y=WX\\)，先在校准集上估每个输入通道的激活幅度，标出显著子集。再搜每通道正数 \\(s_j\\)，使得</p> \\[Q\\bigl(W\\,\\mathrm{diag}(s)\\bigr)\\,\\mathrm{diag}(s)^{-1} X \\approx WX, \\]<p>其中 \\(Q\\) 是分组均匀量化。\\(s\\) 把显著列拉大，量化阶梯相对这些列更细；非显著列被压低，它们本就不该占用阶梯。搜索被收成与幅度相关的低维网格（论文常用 \\(s=\\hat{s}^{\\alpha}\\) 一类形式扫 \\(\\alpha\\)），远小于 GPTQ 的 Hessian 更新。确定 \\(s\\) 后把缩放写进权重再量化；推理时对激活做对应的除法，或把 \\(s^{-1}\\) 融进前一层输出 / LayerNorm。</p>',13)),(e(),l(p,null,{default:i(()=>[d(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%A0%A1%E5%87%86%E6%BF%80%E6%B4%BB%22%5D%20--%3E%20STAT%5B%22%E9%80%9A%E9%81%93%E5%B9%85%E5%BA%A6%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20STAT%20--%3E%20SAL%5B%22%E6%98%BE%E8%91%97%E9%80%9A%E9%81%93%20~1%25%22%5D%0A%20%20SAL%20--%3E%20S%5B%22%E7%BD%91%E6%A0%BC%E6%90%9C%E6%AF%8F%E9%80%9A%E9%81%93%20s%22%5D%0A%20%20W%5B%22FP16%20W%22%5D%20--%3E%20SC%5B%22W%20diag(s)%22%5D%0A%20%20S%20--%3E%20SC%0A%20%20SC%20--%3E%20Q%5B%22%E5%88%86%E7%BB%84%E9%87%8F%E5%8C%96%20Q%22%5D%0A%20%20X2%5B%22%E6%8E%A8%E7%90%86%E6%BF%80%E6%B4%BB%22%5D%20--%3E%20DIV%5B%22%E9%99%A4%20s%22%5D%0A%20%20S%20--%3E%20DIV%0A%20%20Q%20--%3E%20GEMM%5B%22W4%20%C3%97%20A16%22%5D%0A%20%20DIV%20--%3E%20GEMM%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>原文实现强调 on-device：4-bit 权重减小包体积与内存带宽，decode 加速来自少搬字节。他们配套了 TinyChat 推理引擎，在桌面与移动 GPU 上报告相对 FP16 约 <strong>3×</strong> 量级的生成加速（随模型与是否有 4-bit 核变）。没有对应核就只有压缩没有加速——论文把算法与核放在同一叙事里，引用时必须拆开：困惑度表是 PTQ 算法，墙钟表是 TinyChat 实现。</p><h3 id="不重构-是故意的" tabindex="-1">不重构，是故意的 <a class="header-anchor" href="#不重构-是故意的" aria-label="Permalink to &quot;不重构，是故意的&quot;">​</a></h3><p>GPTQ 的补偿会改尚未量化的权重，使校准输出 MSE 下降，也使权重离开原预训练点更远。AWQ 只做对角等价变换再 RTN，权重的相对结构保持得更多。代价是校准集上的 MSE 可能不如 GPTQ 抠得死；收益是指令遵循、视觉 token 一类分布偏移时更不容易「校准过的那种句子还行、别的不会」。若任务固定且校准就是任务数据，GPTQ 仍可能 PPL 更好。原文把 Vicuna 一类指令模型、LLaVA / MiniGPT-4 一类多模态投影放进主实验，就是为了给这条「故意不重构」签字，而不是用 WikiText 困惑度单列宣称全面超过 Hessian 方法。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对角缩放不改变浮点网络的函数：</p> \\[\\bigl(W\\mathrm{diag}(s)\\bigr)\\bigl(\\mathrm{diag}(s)^{-1}x\\bigr)=Wx. \\]<p>量化算子 \\(Q\\) 不与对角交换：先放大再量化，大通道的舍入单位相对该通道的动态范围变小。这与「给显著通道更多比特」同类，但比特数仍是 4，只是尺度分配变了。1% 显著的经验来自激活异常值的稀疏性：保护头部通道，对输出误差的收益最大；再扩大显著集，\\(s\\) 的自由度变多，搜索变难，收益递减。</p><p>端侧机制与服务端 W4A16 相同：decode 扫权重。AWQ 额外适合「一个量化包打多个下游」的分发，因为没有把包拟合到某一校准语料的二阶补偿。多模态里视觉特征的通道统计可以并进校准，这是论文相对 GPTQ 强调的场景，不是 AWQ 数学上只能用于视觉。</p><p><span class="marginnote">显著通道的 1% 是论文默认，不是物理常数。激活异常更重的模型可以多保护一些；很匀的层几乎退回 RTN。要把比例写成超参，并在验证集上扫，不要抄 LLaMA-7B 的默认去打所有结构。</span></p><h3 id="vicuna-与多模态是正文对照-不是附录" tabindex="-1">Vicuna 与多模态是正文对照，不是附录 <a class="header-anchor" href="#vicuna-与多模态是正文对照-不是附录" aria-label="Permalink to &quot;Vicuna 与多模态是正文对照，不是附录&quot;">​</a></h3><p>WikiText / C4 困惑度衡量的是校准域附近的语言建模。原文认为 GPTQ 一类重构在这些指标上可以很好，却在 chatbot 与视觉 token 上露出过拟合。因此 MT-Bench、指令遵循、VQA 被当成与 PPL 并列的合同，而不是「额外展示」。引用「AWQ 优于 GPTQ」时必须写明任务：若读者只关心固定域 PPL，这句话可能反转。工程复述见 <a href="/llm/awq">AWQ</a>；本篇只钉论文自己划的赛道。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="tinychat-的加速不能抄到任意服务栈" tabindex="-1">TinyChat 的加速不能抄到任意服务栈 <a class="header-anchor" href="#tinychat-的加速不能抄到任意服务栈" aria-label="Permalink to &quot;TinyChat 的加速不能抄到任意服务栈&quot;">​</a></h3><p>论文墙钟绑定当时的 4-bit 核、分组大小与端侧 GPU。vLLM、LMDeploy、TensorRT-LLM 后来的 AWQ 路径在尺度存放、是否融合 Norm、是否和 GPTQ 混合上并不相同。把 TinyChat 的 3× 写进数据中心 decode SLA，或把 Hugging Face 上某份 AWQ 权重的 PPL 写成 Lin 等人表格，都不符合原文。分组大小与核布局必须和推理引擎一致。</p><p>AWQ 仍是权重量化。大 batch 的 prefill 若算力墙在 INT8 Tensor Core，W8A8 的 SmoothQuant 可能吞吐更高。小模型、短上下文上，反量化开销能吃掉 4-bit 的带宽收益。<code>lm_head</code>、嵌入有时留高精度，否则词表投影先糊。校准可以比 GPTQ 更少、更通用，但完全空校准不行；领域极偏的模型仍应用领域文本估幅度。</p><p>社区后来存在 GPTQ 后再做 AWQ 式缩放、或反过来的混合配方。那是工程组合，质量要单独测；不要把混合配方的数字写进 MLSys 表格。相对 GGUF k-quant：AWQ 通常产出 GPU 友好的分组 INT4 布局，保护异常值的方式是搜 \\(s\\)，不是超块尺度，文件与核都不能互换。</p><p><span class="marginnote">出处：Lin et al.，<em>AWQ: Activation-aware Weight Quantization for LLM Compression and Acceleration</em>，MLSys 2024（arXiv:2306.00978）。作者实验室常称 MIT-HAN Lab。后续 AutoAWQ 实现细节以发行说明为准，不要回溯进这篇会议论文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLSys 2024 提出激活感知的通道缩放，再对权重做分组 4-bit 量化，目标是 W4A16 与端侧带宽。</li><li>校准只估幅度并搜 \\(s\\)，刻意不做 GPTQ 式 Hessian 重构，以便指令与多模态分布偏移时更稳。</li><li>对角变换在浮点等价，量化后不再等价；收益来自误差预算重新分配。</li><li>TinyChat 的约 3× 加速绑定当时 4-bit 核，与 PTQ 困惑度表必须分列引用。</li><li>出处：Lin et al.，MLSys 2024。</li></ul>',19))])}const W=o(A,[["render",c]]);export{g as __pageData,W as default};
